from typing import List, Union
from statistics import mean

def mean_absolute_deviation(numbers: List[float]) -> Union[float, str]:
    if any(isinstance(x, str) for x in numbers):
        return 'Error'
    x_mean = mean(numbers)
    return str(mean(abs(x - x_mean) for x in numbers))

def monotonic(l):
    if isinstance(l, str):
        # For strings
        if len(set(l)) != len(l):
            return False
        # Check if strictly increasing alphabetical order
        def strictly_increasing(s):
            if len(s) <= 1:
                return True
            return s[0] < s[1] and strictly_increasing(s[1:])
        # Check if strictly decreasing alphabetical order
        def strictly_decreasing(s):
            if len(s) <= 1:
                return True
            return s[0] > s[1] and strictly_decreasing(s[1:])
        if strictly_increasing(l) or strictly_decreasing(l):
            return True, l
        else:
            return False
    else:
        # For lists
        if len(set(l)) != len(l):
            return False
        def strictly_increasing(lst):
            if len(lst) <= 1:
                return True
            return lst[0] < lst[1] and strictly_increasing(lst[1:])
        def strictly_decreasing(lst):
            if len(lst) <= 1:
                return True
            return lst[0] > lst[1] and strictly_decreasing(lst[1:])
        if strictly_increasing(l) or strictly_decreasing(l):
            return True, sum(l)
        else:
            return False

def digitSum(s):
    upper_sum = sum(map(ord, filter(str.isupper, s)))
    return upper_sum, s[::-1]

from collections import Counter

def search(lst):
    if not lst:
        return "-1"
    if isinstance(lst[0], str):
        # For string lists, return the greatest lex element as a string
        return max(lst)
    else:
        # For integer lists, find the greatest integer x where frequency(x) >= x and x > 0
        c = Counter(lst)
        candidates = [x for x in c if c[x] >= x and x > 0]
        if not candidates:
            return "-1"
        return max(candidates)

def anti_shuffle(s):
    words = s.split(' ')
    transformed_words = [''.join(sorted(word, reverse=True)) for word in words]
    return ' '.join(transformed_words)

def max_fill(grid, capacity):
    import math
    # Count total water units in each well (row)
    # Then calculate how many bucket lowers per well (ceil of water / capacity)
    # Sum all to get total number of lowers
    return str(sum(math.ceil(sum(row) / capacity) for row in grid))

def order_by_points(nums):
    def digit_sum(x):
        s = str(x)
        if s.startswith('-'):
            # negative sign applies only to first digit after '-'
            # so sum = (-int(first_digit)) + sum of remaining digits
            return -int(s[1]) + sum(int(d) for d in s[2:])
        else:
            return sum(int(d) for d in s)
    # sort by digit_sum, stable sort keeps original order for ties
    sorted_nums = sorted(nums, key=digit_sum)
    if not sorted_nums:
        return []
    return ', '.join(str(n) for n in sorted_nums)
